package adapters

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"io"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/core"
)

type ClaudeScanner struct {
	Root string
}

func (s ClaudeScanner) Name() string {
	return "claude"
}

func (s ClaudeScanner) Scan(ctx context.Context) core.ScanResult {
	result := core.ScanResult{Source: s.Name()}
	if !core.ExistingDir(s.Root) {
		result.Skipped = true
		result.Message = "Claude projects directory not found"
		return result
	}
	entries, err := os.ReadDir(s.Root)
	if err != nil {
		result.Err = err
		return result
	}
	for _, entry := range entries {
		if ctx.Err() != nil {
			result.Err = ctx.Err()
			return result
		}
		if !entry.IsDir() {
			continue
		}
		projectDir := filepath.Join(s.Root, entry.Name())
		fallbackProjectPath := core.DecodeClaudeProjectDir(entry.Name())
		files, err := os.ReadDir(projectDir)
		if err != nil {
			result.Err = err
			return result
		}
		for _, file := range files {
			if ctx.Err() != nil {
				result.Err = ctx.Err()
				return result
			}
			if file.IsDir() || filepath.Ext(file.Name()) != ".jsonl" {
				continue
			}
			path := filepath.Join(projectDir, file.Name())
			info, statErr := file.Info()
			if statErr != nil {
				result.Err = statErr
				return result
			}
			fileSessionID := strings.TrimSuffix(filepath.Base(path), ".jsonl")
			meta, metaErr := readClaudeMetadata(path, fileSessionID)
			if metaErr != nil {
				result.Err = metaErr
				return result
			}
			nativeID := firstNonEmpty(fileSessionID, meta.SessionID)
			if nativeID == "" {
				nativeID = path
			}
			lastActivity := core.NonZeroTime(meta.LastTimestamp, info.ModTime())
			created := core.NonZeroTime(meta.FirstTimestamp, info.ModTime())
			projectPath := firstNonEmpty(meta.CWD, fallbackProjectPath)
			title := meta.Title
			if title == "" {
				title = "Claude: " + core.ProjectName(projectPath)
			}
			session := core.NewSession("claude", nativeID)
			session.ProjectPath = projectPath
			session.Agent = "claude"
			session.Title = core.Truncate(title, 120)
			session.Status = core.StatusUnknown
			session.LastActivityAt = lastActivity.UTC()
			session.CreatedAt = created.UTC()
			resume := commandWithEnv(
				"CLAUDE_CONFIG_DIR",
				filepath.Dir(s.Root),
				"claude --resume "+core.ShellQuote(nativeID),
			)
			session.ResumeCommand = resumeInDirectory(projectPath, resume)
			session.RawPath = path
			result.Sessions = append(result.Sessions, session)
		}
	}
	result.SessionSnapshotComplete = true
	return result
}

type claudeMetadata struct {
	SessionID      string
	CWD            string
	GitBranch      string
	Title          string
	FirstTimestamp time.Time
	LastTimestamp  time.Time
}

func readClaudeMetadata(path, expectedSessionID string) (claudeMetadata, error) {
	file, err := os.Open(path)
	if err != nil {
		return claudeMetadata{}, err
	}
	defer file.Close() //nolint:errcheck
	var meta claudeMetadata
	titleRank := 0
	reader := bufio.NewReaderSize(file, 64*1024)
	for {
		line, err := readBoundedLine(reader, 2*1024*1024)
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return meta, err
		}
		if len(line) == 0 {
			continue
		}
		var row map[string]any
		if err := json.Unmarshal(line, &row); err != nil {
			continue
		}
		rowSessionID := stringValue(row["sessionId"])
		if expectedSessionID != "" && rowSessionID != "" && rowSessionID != expectedSessionID {
			continue
		}
		if meta.SessionID == "" && rowSessionID != "" {
			meta.SessionID = rowSessionID
		}
		if value := stringValue(row["cwd"]); value != "" && meta.CWD == "" {
			meta.CWD = value
		}
		if value := stringValue(row["gitBranch"]); value != "" && meta.GitBranch == "" {
			meta.GitBranch = value
		}
		switch stringValue(row["type"]) {
		case "custom-title":
			setClaudeTitle(&meta, &titleRank, stringValue(row["customTitle"]), 5)
		case "ai-title":
			setClaudeTitle(&meta, &titleRank, stringValue(row["aiTitle"]), 4)
		case "agent-name":
			setClaudeTitle(&meta, &titleRank, stringValue(row["agentName"]), 3)
		case "summary":
			setClaudeTitle(&meta, &titleRank, stringValue(row["summary"]), 2)
		default:
			setClaudeTitle(&meta, &titleRank, stringValue(row["slug"]), 1)
		}
		ts := parseTimestamp(row)
		if ts.IsZero() {
			continue
		}
		if meta.FirstTimestamp.IsZero() || ts.Before(meta.FirstTimestamp) {
			meta.FirstTimestamp = ts
		}
		if meta.LastTimestamp.IsZero() || ts.After(meta.LastTimestamp) {
			meta.LastTimestamp = ts
		}
	}
	return meta, nil
}

func readBoundedLine(reader *bufio.Reader, limit int) ([]byte, error) {
	line := make([]byte, 0, 64*1024)
	oversized := false
	for {
		fragment, prefix, err := reader.ReadLine()
		if err != nil {
			return nil, err
		}
		if !oversized {
			if len(line)+len(fragment) > limit {
				line = nil
				oversized = true
			} else {
				line = append(line, fragment...)
			}
		}
		if !prefix {
			if oversized {
				return nil, nil
			}
			return line, nil
		}
	}
}

func setClaudeTitle(meta *claudeMetadata, currentRank *int, title string, rank int) {
	title = strings.TrimSpace(title)
	if title == "" || rank < *currentRank {
		return
	}
	meta.Title = title
	*currentRank = rank
}

func stringValue(value any) string {
	text, _ := value.(string)
	return strings.TrimSpace(text)
}

func parseTimestamp(row map[string]any) time.Time {
	for _, key := range []string{"timestamp", "created_at", "createdAt", "time"} {
		raw, ok := row[key].(string)
		if !ok || raw == "" {
			continue
		}
		for _, layout := range []string{time.RFC3339Nano, time.RFC3339, "2006-01-02 15:04:05"} {
			t, err := time.Parse(layout, raw)
			if err == nil {
				return t.UTC()
			}
		}
	}
	return time.Time{}
}

func readTextCandidatesFromJSONL(path string, limit int) ([]string, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer file.Close() //nolint:errcheck
	var out []string
	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 0, 64*1024), 2*1024*1024)
	for scanner.Scan() {
		if limit > 0 && len(out) >= limit {
			break
		}
		var row any
		if err := json.Unmarshal(scanner.Bytes(), &row); err != nil {
			continue
		}
		for _, text := range extractText(row) {
			text = cleanCandidate(text)
			if text != "" {
				out = append(out, text)
				if limit > 0 && len(out) >= limit {
					break
				}
			}
		}
	}
	if err := scanner.Err(); err != nil && !errors.Is(err, bufio.ErrTooLong) {
		return out, err
	}
	return out, nil
}

package adapters

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/core"
)

func TestClaudeScannerUsesExactTranscriptMetadata(t *testing.T) {
	root := t.TempDir()
	project := filepath.Join(root, "-Users-test-my-project-with-hyphen")
	if err := os.MkdirAll(project, 0o755); err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(project, "exact-id.jsonl")
	data := strings.Join([]string{
		`{"type":"user","sessionId":"exact-id","cwd":"/Users/test/my-project-with-hyphen","gitBranch":"feature/auth","timestamp":"2026-01-01T00:00:00Z"}`,
		`{"type":"ai-title","sessionId":"exact-id","aiTitle":"AI title"}`,
		`{"type":"custom-title","sessionId":"exact-id","customTitle":"User title"}`,
		`{"type":"assistant","sessionId":"exact-id","cwd":"/Users/test/my-project-with-hyphen","timestamp":"2026-01-01T01:00:00Z"}`,
		`{"type":"custom-title","sessionId":"sidechain-id","cwd":"/wrong","customTitle":"Wrong sidechain title","timestamp":"2026-01-02T01:00:00Z"}`,
		`{"partial":`,
	}, "\n")
	if err := os.WriteFile(path, []byte(data), 0o644); err != nil {
		t.Fatal(err)
	}

	result := (ClaudeScanner{Root: root}).Scan(context.Background())
	if result.Err != nil {
		t.Fatal(result.Err)
	}
	if len(result.Sessions) != 1 {
		t.Fatalf("expected one session, got %d", len(result.Sessions))
	}
	session := result.Sessions[0]
	if session.NativeID != "exact-id" {
		t.Fatalf("native id = %q", session.NativeID)
	}
	if session.ProjectPath != "/Users/test/my-project-with-hyphen" {
		t.Fatalf("project path = %q", session.ProjectPath)
	}
	if session.Title != "User title" {
		t.Fatalf("title = %q", session.Title)
	}
	if session.CreatedAt != time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC) {
		t.Fatalf("created = %s", session.CreatedAt)
	}
	if session.LastActivityAt != time.Date(2026, 1, 1, 1, 0, 0, 0, time.UTC) {
		t.Fatalf("updated = %s", session.LastActivityAt)
	}
	wantResume := "cd '/Users/test/my-project-with-hyphen' && CLAUDE_CONFIG_DIR=" +
		core.ShellQuote(filepath.Dir(root)) + " claude --resume 'exact-id'"
	if session.ResumeCommand != wantResume {
		t.Fatalf("resume = %q, want %q", session.ResumeCommand, wantResume)
	}
}

func TestClaudeScannerSkipsOversizedRowsAndContinues(t *testing.T) {
	root := t.TempDir()
	project := filepath.Join(root, "-repo")
	if err := os.MkdirAll(project, 0o755); err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(project, "session.jsonl")
	oversized := `{"type":"assistant","sessionId":"session","payload":"` +
		strings.Repeat("x", 2*1024*1024+1024) + `"}`
	data := oversized + "\n" +
		`{"type":"custom-title","sessionId":"session","cwd":"/repo","customTitle":"After large row","timestamp":"2026-01-01T00:00:00Z"}` + "\n"
	if err := os.WriteFile(path, []byte(data), 0o644); err != nil {
		t.Fatal(err)
	}
	result := (ClaudeScanner{Root: root}).Scan(context.Background())
	if result.Err != nil || len(result.Sessions) != 1 {
		t.Fatalf("unexpected result: %+v", result)
	}
	if result.Sessions[0].Title != "After large row" {
		t.Fatalf("title after oversized row = %q", result.Sessions[0].Title)
	}
}

func TestClaudeScannerFallsBackToEncodedDirectory(t *testing.T) {
	root := t.TempDir()
	project := filepath.Join(root, "-tmp-project")
	if err := os.MkdirAll(project, 0o755); err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(project, "session-1.jsonl")
	if err := os.WriteFile(path, []byte(`{"timestamp":"2026-01-01T00:00:00Z"}`+"\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	result := (ClaudeScanner{Root: root}).Scan(context.Background())
	if result.Err != nil || len(result.Sessions) != 1 {
		t.Fatalf("unexpected result: %+v", result)
	}
	if result.Sessions[0].ProjectPath != "/tmp/project" {
		t.Fatalf("fallback path = %q", result.Sessions[0].ProjectPath)
	}
}

package adapters

import (
	"context"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/core"
	"gopkg.in/yaml.v3"
)

type CopilotScanner struct {
	Root string
}

func (s CopilotScanner) Name() string {
	return "copilot"
}

func (s CopilotScanner) Scan(ctx context.Context) core.ScanResult {
	result := core.ScanResult{Source: s.Name()}
	if !core.ExistingDir(s.Root) {
		result.Skipped = true
		result.Message = "Copilot session-state directory not found"
		return result
	}
	entries, err := os.ReadDir(s.Root)
	if err != nil {
		result.Err = err
		return result
	}
	for _, entry := range entries {
		if ctx.Err() != nil {
			result.Err = ctx.Err()
			return result
		}
		if strings.HasPrefix(entry.Name(), ".") || !entry.IsDir() {
			continue
		}
		path := filepath.Join(s.Root, entry.Name())
		workspacePath := filepath.Join(path, "workspace.yaml")
		if !core.ExistingFile(workspacePath) {
			continue
		}
		info, err := entry.Info()
		if err != nil {
			result.Err = err
			return result
		}
		metadata, err := readCopilotWorkspace(workspacePath)
		if err != nil {
			result.Err = err
			return result
		}
		workspaceModified := info.ModTime()
		if workspaceInfo, statErr := os.Stat(workspacePath); statErr == nil {
			workspaceModified = workspaceInfo.ModTime()
		}
		nativeID := firstNonEmpty(metadata.ID, entry.Name())
		projectPath := firstNonEmpty(metadata.CWD, metadata.GitRoot)
		title := metadata.Name
		if title == "" && metadata.Repository != "" {
			title = "Copilot: " + metadata.Repository
		}
		if title == "" {
			title = "Copilot: " + core.ProjectName(projectPath)
		}
		created := core.NonZeroTime(parseTimeString(metadata.CreatedAt), workspaceModified)
		updated := parseTimeString(metadata.UpdatedAt)
		if updated.IsZero() {
			updated = core.NonZeroTime(created, workspaceModified)
		}
		session := core.NewSession("copilot", nativeID)
		session.ProjectPath = projectPath
		session.Agent = "copilot"
		session.Title = core.Truncate(title, 120)
		session.Status = core.StatusUnknown
		session.LastActivityAt = updated.UTC()
		session.CreatedAt = created.UTC()
		resume := commandWithEnv(
			"COPILOT_HOME",
			filepath.Dir(s.Root),
			"copilot --resume="+core.ShellQuote(nativeID),
		)
		session.ResumeCommand = resumeInDirectory(projectPath, resume)
		session.RawPath = path
		result.Sessions = append(result.Sessions, session)
	}
	sort.Slice(result.Sessions, func(i, j int) bool {
		return result.Sessions[i].LastActivityAt.After(result.Sessions[j].LastActivityAt)
	})
	result.SessionSnapshotComplete = true
	return result
}

type copilotWorkspace struct {
	ID         string `yaml:"id"`
	CWD        string `yaml:"cwd"`
	GitRoot    string `yaml:"git_root"`
	Repository string `yaml:"repository"`
	HostType   string `yaml:"host_type"`
	Branch     string `yaml:"branch"`
	ClientName string `yaml:"client_name"`
	Name       string `yaml:"name"`
	UserNamed  bool   `yaml:"user_named"`
	CreatedAt  string `yaml:"created_at"`
	UpdatedAt  string `yaml:"updated_at"`
}

func readCopilotWorkspace(path string) (copilotWorkspace, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return copilotWorkspace{}, err
	}
	var metadata copilotWorkspace
	if err := yaml.Unmarshal(data, &metadata); err != nil {
		return copilotWorkspace{}, err
	}
	return metadata, nil
}

func parseTimeString(value string) time.Time {
	value = strings.TrimSpace(value)
	for _, layout := range []string{time.RFC3339Nano, time.RFC3339, "2006-01-02 15:04:05"} {
		if parsed, err := time.Parse(layout, value); err == nil {
			return parsed.UTC()
		}
	}
	return time.Time{}
}

package adapters

import (
	"context"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/core"
)

func TestCopilotScannerReadsWorkspaceMetadata(t *testing.T) {
	root := t.TempDir()
	writeCopilotWorkspace(t, root, "session-named", `
id: exact-id
cwd: /repo/worktree
git_root: /repo
repository: owner/repo
branch: feature/auth
name: Refactor auth
created_at: 2026-01-01T00:00:00Z
updated_at: 2026-01-01T02:00:00Z
`)
	writeCopilotWorkspace(t, root, "session-unnamed", `
id: fallback-id
cwd: /repo/other
repository: owner/other
created_at: 2026-01-02T00:00:00Z
updated_at: 2026-01-02T01:00:00Z
`)
	if err := os.Mkdir(filepath.Join(root, "not-a-session"), 0o755); err != nil {
		t.Fatal(err)
	}

	result := (CopilotScanner{Root: root}).Scan(context.Background())
	if result.Err != nil {
		t.Fatal(result.Err)
	}
	if len(result.Sessions) != 2 {
		t.Fatalf("sessions = %d", len(result.Sessions))
	}
	named := findNativeSession(t, result.Sessions, "exact-id")
	if named.ProjectPath != "/repo/worktree" || named.Title != "Refactor auth" {
		t.Fatalf("unexpected named session: %+v", named)
	}
	if named.CreatedAt != time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC) ||
		named.LastActivityAt != time.Date(2026, 1, 1, 2, 0, 0, 0, time.UTC) {
		t.Fatalf("unexpected timestamps: %+v", named)
	}
	wantResume := "cd '/repo/worktree' && COPILOT_HOME=" +
		core.ShellQuote(filepath.Dir(root)) + " copilot --resume='exact-id'"
	if named.ResumeCommand != wantResume {
		t.Fatalf("resume = %q, want %q", named.ResumeCommand, wantResume)
	}
	unnamed := findNativeSession(t, result.Sessions, "fallback-id")
	if unnamed.Title != "Copilot: owner/other" {
		t.Fatalf("fallback title = %q", unnamed.Title)
	}
}

func TestCopilotScannerRejectsMalformedWorkspace(t *testing.T) {
	root := t.TempDir()
	writeCopilotWorkspace(t, root, "broken", "id: [\n")
	result := (CopilotScanner{Root: root}).Scan(context.Background())
	if result.Err == nil {
		t.Fatal("expected malformed workspace error")
	}
}

func writeCopilotWorkspace(t *testing.T, root, id, content string) {
	t.Helper()
	dir := filepath.Join(root, id)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "workspace.yaml"), []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
}

package adapters

import (
	"bytes"
	"context"
	"database/sql"
	"os"
	"path/filepath"
	"testing"

	"github.com/jdbencardinop/tesserasessions/internal/core"
)

func TestHermesHistoryScannerReadsCurrentMetadataOnly(t *testing.T) {
	path := filepath.Join(t.TempDir(), "state.db")
	db := createSQLiteFixture(t, path, `
		CREATE TABLE sessions (
			id TEXT PRIMARY KEY,
			source TEXT NOT NULL,
			title TEXT,
			cwd TEXT,
			git_repo_root TEXT,
			started_at REAL NOT NULL,
			ended_at REAL,
			last_activity_at REAL,
			parent_session_id TEXT,
			archived INTEGER DEFAULT 0,
			end_reason TEXT,
			model_config TEXT
		);
		CREATE TABLE messages (
			id INTEGER PRIMARY KEY,
			session_id TEXT,
			content TEXT,
			timestamp REAL,
			active INTEGER DEFAULT 1
		);
	`)
	mustExec(t, db, `INSERT INTO sessions (
			id, source, title, cwd, git_repo_root, started_at, ended_at,
			last_activity_at, parent_session_id, archived, end_reason, model_config
		) VALUES
		('root', 'cli', 'Fix build', '/repo/worktree', '/repo', 1000.25, 1100, 1100, NULL, 0, 'compression', NULL),
		('child', 'cli', 'Fix build #2', '/repo/new-worktree', '/repo', 1201, NULL, 1300.5, 'root', 0, NULL, NULL),
		('delegate', 'cli', 'Wrong delegate', '/wrong/delegate', '/wrong', 1202, NULL, 9999, 'root', 0, NULL, '{"_delegate_from":"root"}'),
		('branch', 'cli', 'Wrong branch', '/wrong/branch', '/wrong', 1203, NULL, 9998, 'root', 0, NULL, '{"_branched_from":"root"}'),
		('tool', 'tool', 'Wrong tool', '/wrong/tool', '/wrong', 1204, NULL, 9997, 'root', 0, NULL, NULL),
		('orphan-delegate', 'cli', 'Orphan delegate', '/wrong/orphan', '/wrong', 1205, NULL, 9996, NULL, 0, NULL, '{"_delegate_from":"deleted"}'),
		('orphan-branch', 'cli', 'Orphan branch', '/wrong/orphan', '/wrong', 1206, NULL, 9995, NULL, 0, NULL, '{"_branched_from":"deleted"}'),
		('archived', 'cli', 'Old', '/repo', '/repo', 900, 950, 950, NULL, 1, NULL, NULL),
		('gateway', 'telegram', 'Chat', NULL, NULL, 1000, NULL, NULL, NULL, 0, NULL, NULL)`)
	mustExec(t, db, `INSERT INTO messages VALUES
		(1, 'root', 'private transcript content', 1150, 1),
		(2, 'child', 'latest private transcript content', 1400.5, 1)`)
	if err := db.Close(); err != nil {
		t.Fatal(err)
	}
	before := readFixtureBytes(t, path)

	result := (HermesHistoryScanner{Database: path}).Scan(context.Background())
	if result.Err != nil {
		t.Fatal(result.Err)
	}
	if len(result.Sessions) != 1 {
		t.Fatalf("sessions = %d, want 1", len(result.Sessions))
	}
	session := result.Sessions[0]
	if session.NativeID != "root" || session.Title != "Fix build #2" || session.ProjectPath != "/repo/new-worktree" {
		t.Fatalf("unexpected session: %+v", session)
	}
	if session.CreatedAt.Unix() != 1000 || session.LastActivityAt.Unix() != 1400 {
		t.Fatalf("unexpected times: created=%s updated=%s", session.CreatedAt, session.LastActivityAt)
	}
	wantResume := "cd '/repo/new-worktree' && HERMES_HOME=" +
		core.ShellQuote(filepath.Dir(path)) +
		" HERMES_S6_SUPERVISED_CHILD='1' hermes --resume 'root'"
	if session.ResumeCommand != wantResume {
		t.Fatalf("resume = %q", session.ResumeCommand)
	}
	if !result.SessionSnapshotComplete {
		t.Fatal("successful Hermes scan must be authoritative")
	}
	if !bytes.Equal(before, readFixtureBytes(t, path)) {
		t.Fatal("Hermes scanner modified the database")
	}
}

func TestHermesResumeCommandKeepsProfileScopedHome(t *testing.T) {
	database := filepath.Join("/hermes", "profiles", "coder", "state.db")
	want := "HERMES_HOME='/hermes/profiles/coder' hermes --resume 'session'"
	if got := hermesResumeCommand(database, "session"); got != want {
		t.Fatalf("resume = %q, want %q", got, want)
	}
}

func TestOpenCodeScannerReadsCurrentMetadataOnly(t *testing.T) {
	path := filepath.Join(t.TempDir(), "opencode.db")
	db := createSQLiteFixture(t, path, `
		CREATE TABLE project (
			id TEXT PRIMARY KEY,
			worktree TEXT NOT NULL,
			name TEXT
		);
		CREATE TABLE "session" (
			id TEXT PRIMARY KEY,
			slug TEXT,
			title TEXT,
			project_id TEXT NOT NULL,
			parent_id TEXT,
			directory TEXT,
			path TEXT,
			time_created INTEGER NOT NULL,
			time_updated INTEGER NOT NULL,
			time_archived INTEGER
		);
	`)
	mustExec(t, db, `INSERT INTO project VALUES ('project', '/repo', 'app')`)
	mustExec(t, db, `INSERT INTO "session" VALUES
		('root', 'happy-dolphin', 'Refactor auth', 'project', NULL, '/repo/packages/api', 'packages/api', 1000000, 2000000, NULL),
		('child', 'child', 'Child', 'project', 'root', '/repo', NULL, 1000000, 2000000, NULL),
		('archived', 'old', 'Old', 'project', NULL, '/repo', NULL, 1000000, 2000000, 3000000),
		('fallback', 'quiet-panda', '', 'project', NULL, '', 'packages/web', 3000000, 4000000, NULL)`)
	if err := db.Close(); err != nil {
		t.Fatal(err)
	}
	before := readFixtureBytes(t, path)

	result := (OpenCodeScanner{Database: path}).Scan(context.Background())
	if result.Err != nil {
		t.Fatal(result.Err)
	}
	if len(result.Sessions) != 2 {
		t.Fatalf("sessions = %d, want 2", len(result.Sessions))
	}
	root := findNativeSession(t, result.Sessions, "root")
	if root.ProjectPath != "/repo/packages/api" || root.Title != "Refactor auth" {
		t.Fatalf("unexpected root: %+v", root)
	}
	wantResume := "cd '/repo/packages/api' && OPENCODE_DB=" +
		core.ShellQuote(path) + " opencode --session 'root'"
	if root.ResumeCommand != wantResume {
		t.Fatalf("resume = %q", root.ResumeCommand)
	}
	fallback := findNativeSession(t, result.Sessions, "fallback")
	if fallback.ProjectPath != "/repo/packages/web" || fallback.Title != "quiet-panda" {
		t.Fatalf("unexpected fallback: %+v", fallback)
	}
	if !result.SessionSnapshotComplete {
		t.Fatal("successful OpenCode scan must be authoritative")
	}
	if !bytes.Equal(before, readFixtureBytes(t, path)) {
		t.Fatal("OpenCode scanner modified the database")
	}
}

func TestHistorySQLiteScannersSkipMissingAndRejectMalformed(t *testing.T) {
