		t.Fatalf("drive URI = %q, want %q", got, want)
	}
	if got, want := sqliteFileURIForOS(`\\server\share\source.db`, "windows"), "file://server/share/source.db"; got != want {
		t.Fatalf("UNC URI = %q, want %q", got, want)
