	cmd.Flags().BoolVar(&useFZF, "fzf", false, "select interactively with fzf")
	cmd.Flags().BoolVar(&showSelected, "show", false, "show the selected session when using --fzf")
	cmd.Flags().BoolVar(&jsonOutput, "json", false, "print JSON")
	return cmd
