func printSessions(sessions []core.Session, groupProject bool) error {
	w := tabwriter.NewWriter(os.Stdout, 0, 0, 2, ' ', 0)
	if groupProject {
		current := ""
		for _, sess := range sessions {
			project := core.ProjectName(sess.ProjectPath)
			if project != current {
				if current != "" {
					fmt.Fprintln(w)
				}
				current = project
				fmt.Fprintf(w, "%s\n", project)
				fmt.Fprintln(w, "ID\tPIN\tSOURCE\tSTATUS\tLAST ACTIVITY\tAGENT\tTAGS\tTITLE")
			}
			printSessionRow(w, sess)
		}
		return w.Flush()
	}
	fmt.Fprintln(w, "ID\tPIN\tSOURCE\tSTATUS\tLAST ACTIVITY\tAGENT\tPROJECT\tTAGS\tTITLE")
	for _, sess := range sessions {
		fmt.Fprintf(w, "%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n",
			sess.ID, pinLabel(sess), sess.Source, sess.Status, core.FormatTime(sess.LastActivityAt),
			sess.Agent, core.ProjectName(sess.ProjectPath), sess.Tags, core.Truncate(sess.Title, 52))
	}
	return w.Flush()
}

func printSessionRow(w *tabwriter.Writer, sess core.Session) {
	fmt.Fprintf(w, "%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n",
		sess.ID, pinLabel(sess), sess.Source, sess.Status, core.FormatTime(sess.LastActivityAt),
		sess.Agent, sess.Tags, core.Truncate(sess.Title, 52))
}

func pinLabel(sess core.Session) string {
	if sess.Pinned {
		return "*"
	}
	return ""
}

func contentMatches(ctx context.Context, sessions []core.Session, query string) []core.Session {
	query = strings.ToLower(query)
	var out []core.Session
	for _, sess := range sessions {
		if sess.RawPath == "" {
			continue
		}
		items, err := adapters.ReadTextCandidates(sess.RawPath, 80)
		if err != nil {
			continue
		}
		for _, item := range items {
			if ctx.Err() != nil {
				return out
			}
			if strings.Contains(strings.ToLower(item), query) {
				if sess.GoalSummary == "" {
					sess.GoalSummary = core.Truncate(item, 180)
				}
				out = append(out, sess)
				break
			}
		}
	}
	return out
}

func runFZF(sessions []core.Session) (string, error) {
	if _, err := exec.LookPath("fzf"); err != nil {
		return "", fmt.Errorf("fzf not found in PATH; run without --fzf or install fzf")
	}
	var input strings.Builder
	for _, sess := range sessions {
		fmt.Fprintf(&input, "%s\t%s\t%s\t%s\t%s\n",
			sess.ID, sess.Source, core.ProjectName(sess.ProjectPath), sess.Title, sess.GoalSummary)
	}
	fzf := exec.Command("fzf", "--with-nth=1,2,3,4,5", "--delimiter=\t")
	fzf.Stdin = strings.NewReader(input.String())
	fzf.Stderr = os.Stderr
	out, err := fzf.Output()
	if err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) && exitErr.ExitCode() == 130 {
			return "", nil
		}
		return "", err
	}
	return strings.TrimSpace(string(out)), nil
}

func validStatus(status string) bool {
	switch status {
	case core.StatusNeedsAttention, core.StatusWorking, core.StatusIdle, core.StatusDone, core.StatusStale, core.StatusUnknown:
		return true
	default:
		return false
	}
}

func sourcePath(cfg config.Config, source string) string {
	switch source {
	case "claude":
		return cfg.Sources.ClaudeProjects
	case "copilot":
		return cfg.Sources.CopilotSessionState
	case "hermes":
		return cfg.Sources.HermesDatabase
	case "opencode":
		return cfg.Sources.OpenCodeDatabase
	default:
		return ""
	}
}

func printSession(sess core.Session) {
	fmt.Printf("ID: %s\n", sess.ID)
	fmt.Printf("Source: %s\n", sess.Source)
	fmt.Printf("Native ID: %s\n", sess.NativeID)
	fmt.Printf("Agent: %s\n", sess.Agent)
	fmt.Printf("Status: %s\n", sess.Status)
	fmt.Printf("Title: %s\n", sess.Title)
	if sess.TitleSource != "" {
		fmt.Printf("Title source: %s\n", sess.TitleSource)
	}
	if sess.GoalSummary != "" {
		fmt.Printf("Goal: %s\n", sess.GoalSummary)
	}
	if sess.Pinned {
		fmt.Println("Pinned: true")
	}
	if sess.Tags != "" {
		fmt.Printf("Tags: %s\n", sess.Tags)
	}
	fmt.Printf("Project: %s\n", firstNonEmpty(sess.ProjectPath, "-"))
	fmt.Printf("Last activity: %s\n", core.FormatTime(sess.LastActivityAt))
	if sess.AttachCommand != "" {
		fmt.Printf("Attach: %s\n", sess.AttachCommand)
	}
	if sess.ResumeCommand != "" {
		fmt.Printf("Resume: %s\n", sess.ResumeCommand)
	}
	if sess.RawPath != "" {
		fmt.Printf("Raw path: %s\n", sess.RawPath)
	}
}

func existsLabel(path string) string {
	if core.ExistingDir(path) || core.ExistingFile(path) {
		return "found"
	}
	return "missing"
}

func friendlySessionErr(ref string, err error) error {
	if errors.Is(err, sql.ErrNoRows) {
		return fmt.Errorf("session %q not found; run tss list or tss scan", ref)
	}
	return err
}

func openCommand(backend string, sess core.Session) string {
	if backend == "tmux" || !toolExists("herdr") {
		name := "tss-" + core.SanitizeName(core.ProjectName(sess.ProjectPath)+"-"+sess.ID)
		return "tmux new-session -A -s " + core.ShellQuote(name) + " -c " + core.ShellQuote(sess.ProjectPath)
	}
	return "herdr workspace create --cwd " + core.ShellQuote(sess.ProjectPath) + " --label " + core.ShellQuote(sess.Title)
}

func sendCommand(rt core.RuntimeInstance, text string) (string, error) {
	switch rt.Backend {
	case "herdr":
		return "herdr agent prompt " + core.ShellQuote(rt.NativeID) + " " + core.ShellQuote(text), nil
	case "tmux":
		return "tmux send-keys -t " + core.ShellQuote(rt.NativeID) + " " + core.ShellQuote(text) + " Enter", nil
	default:
		return "", fmt.Errorf("backend %q cannot send text yet", rt.Backend)
	}
}

func readCommand(rt core.RuntimeInstance, lines int) (string, error) {
	if lines <= 0 {
		lines = 80
	}
	switch rt.Backend {
	case "herdr":
		return "herdr agent read " + core.ShellQuote(rt.NativeID) + " --source recent --lines " + fmt.Sprint(lines), nil
	case "tmux":
		return "tmux capture-pane -p -t " + core.ShellQuote(rt.NativeID) + " -S -" + fmt.Sprint(lines), nil
	default:
		return "", fmt.Errorf("backend %q cannot read output yet", rt.Backend)
	}
}

func runCommand(rt core.RuntimeInstance, sess core.Session, command string) (string, error) {
	command = strings.TrimSpace(command)
	if command == "" {
		return "", fmt.Errorf("command cannot be empty")
	}
	cwd := firstNonEmpty(rt.ProjectPath, sess.ProjectPath)
	switch rt.Backend {
	case "herdr":
		pane := firstNonEmpty(rt.Surface, rt.NativeID)
		if pane == "" {
			return "", fmt.Errorf("herdr runtime has no pane target")
		}
		split := "herdr pane split " + core.ShellQuote(pane) + " --direction right --no-focus"
		if cwd != "" {
			split += " --cwd " + core.ShellQuote(cwd)
		}
		return "pane=$(" + split + " | python3 -c 'import json,sys; print(json.load(sys.stdin)[\"result\"][\"pane\"][\"pane_id\"])')" +
			" && herdr pane run \"$pane\" " + core.ShellQuote(command), nil
	case "tmux":
		args := "tmux split-window -h -t " + core.ShellQuote(rt.NativeID)
		if cwd != "" {
			args += " -c " + core.ShellQuote(cwd)
		}
		return args + " " + core.ShellQuote(command), nil
	default:
		return "", fmt.Errorf("backend %q cannot run commands yet", rt.Backend)
	}
}

func runInteractive(command string) error {
	c := exec.Command("sh", "-lc", command)
	c.Stdin = os.Stdin
	c.Stdout = os.Stdout
	c.Stderr = os.Stderr
	return c.Run()
}

func toolExists(name string) bool {
	_, err := exec.LookPath(name)
	return err == nil
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			return value
		}
	}
	return ""
}

func init() {
	cobra.EnableCommandSorting = false
	_ = context.Background()
	_ = time.Now()
}

package cli

import (
	"context"
	"database/sql"
	"errors"
	"path/filepath"
	"testing"

	"github.com/jdbencardinop/tesserasessions/internal/core"
	"github.com/jdbencardinop/tesserasessions/internal/store"
)

func TestPersistScanRuntimesOnlyPrunesCompleteSnapshots(t *testing.T) {
	db, err := store.Open(filepath.Join(t.TempDir(), "sessions.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close() //nolint:errcheck

	ctx := context.Background()
	runtime := core.RuntimeInstance{
		ID:        "tmux-1",
		SessionID: "session-1",
		Backend:   "tmux",
		NativeID:  "%1",
		Status:    core.StatusIdle,
	}
	if err := db.UpsertRuntime(ctx, runtime); err != nil {
		t.Fatal(err)
	}

	if err := persistScanRuntimes(ctx, db, core.ScanResult{
		Source:  "tmux",
		Skipped: true,
		Message: "tmux unavailable",
	}); err != nil {
		t.Fatal(err)
	}
	if _, err := db.RuntimeForSession(ctx, "session-1", "tmux"); err != nil {
		t.Fatalf("incomplete scan pruned prior row: %v", err)
	}

	if err := persistScanRuntimes(ctx, db, core.ScanResult{
		Source:           "tmux",
		SnapshotComplete: true,
		Err:              errors.New("provider failed after producing partial data"),
	}); err != nil {
		t.Fatal(err)
	}
	if _, err := db.RuntimeForSession(ctx, "session-1", "tmux"); err != nil {
		t.Fatalf("failed complete scan pruned prior row: %v", err)
	}

	if err := persistScanRuntimes(ctx, db, core.ScanResult{
		Source:           "tmux",
		SnapshotComplete: true,
	}); err != nil {
		t.Fatal(err)
	}
	if _, err := db.RuntimeForSession(ctx, "session-1", "tmux"); !errors.Is(err, sql.ErrNoRows) {
		t.Fatalf("complete empty scan should prune row, got %v", err)
	}
}

func TestPersistScanSessionsOnlyPrunesCompleteSnapshots(t *testing.T) {
	db, err := store.Open(filepath.Join(t.TempDir(), "sessions.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close() //nolint:errcheck
	ctx := context.Background()

	session := core.NewSession("opencode", "session-1")
	session.Title = "Session"
	if err := db.UpsertSession(ctx, session); err != nil {
		t.Fatal(err)
	}
	if err := persistScanSessions(ctx, db, core.ScanResult{
		Source:  "opencode",
		Skipped: true,
		Message: "database unavailable",
	}); err != nil {
		t.Fatal(err)
	}
	if _, err := db.GetSession(ctx, session.ID); err != nil {
		t.Fatalf("incomplete scan pruned prior session: %v", err)
	}

	if err := persistScanSessions(ctx, db, core.ScanResult{
		Source:                  "opencode",
		SessionSnapshotComplete: true,
	}); err != nil {
		t.Fatal(err)
	}
	if _, err := db.GetSession(ctx, session.ID); !errors.Is(err, sql.ErrNoRows) {
		t.Fatalf("complete empty scan should prune session, got %v", err)
	}
}

package config

import (
	"errors"
	"os"
	"path/filepath"
	"runtime"
	"strings"

	"gopkg.in/yaml.v3"
)

type Config struct {
	DataDir    string        `yaml:"data_dir"`
	Database   string        `yaml:"database"`
	Live       LiveConfig    `yaml:"live"`
	Sources    SourcesConfig `yaml:"sources"`
	Summarizer SummaryConfig `yaml:"summarizer"`
}

type LiveConfig struct {
	DefaultBackend string `yaml:"default_backend"`
}

type SourcesConfig struct {
	ClaudeProjects      string `yaml:"claude_projects"`
	CopilotSessionState string `yaml:"copilot_session_state"`
	HermesDatabase      string `yaml:"hermes_database"`
	OpenCodeDatabase    string `yaml:"opencode_database"`
}

type SummaryConfig struct {
	RemoteCommand string `yaml:"remote_command"`
}

func ConfigPath() string {
	if path := os.Getenv("TSS_CONFIG"); path != "" {
		return path
	}
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".config", "tesserasessions", "config.yaml")
}

func DefaultDataDir() string {
	if path := os.Getenv("TSS_DATA_DIR"); path != "" {
		return path
	}
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".local", "share", "tesserasessions")
}

func DefaultConfig() Config {
	home, _ := os.UserHomeDir()
	claudeRoot := filepath.Join(home, ".claude")
	if env := os.Getenv("CLAUDE_CONFIG_DIR"); env != "" {
		claudeRoot = env
	}
	copilotRoot := filepath.Join(home, ".copilot")
	if env := os.Getenv("COPILOT_HOME"); env != "" {
		copilotRoot = env
	}
	dataDir := DefaultDataDir()
	return Config{
		DataDir:  dataDir,
		Database: filepath.Join(dataDir, "sessions.db"),
		Live: LiveConfig{
			DefaultBackend: "herdr",
		},
		Sources: SourcesConfig{
			ClaudeProjects:      filepath.Join(claudeRoot, "projects"),
			CopilotSessionState: filepath.Join(copilotRoot, "session-state"),
			HermesDatabase:      defaultHermesDatabase(home),
			OpenCodeDatabase:    defaultOpenCodeDatabase(home),
		},
	}
}

func Load(path string) (Config, error) {
	cfg := DefaultConfig()
	if path == "" {
		path = ConfigPath()
	}
	data, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return cfg, nil
		}
		return cfg, err
	}
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return cfg, err
	}
	cfg.DataDir = ExpandPath(firstNonEmpty(cfg.DataDir, DefaultDataDir()))
	cfg.Database = ExpandPath(firstNonEmpty(cfg.Database, filepath.Join(cfg.DataDir, "sessions.db")))
	cfg.Sources.ClaudeProjects = ExpandPath(firstNonEmpty(cfg.Sources.ClaudeProjects, DefaultConfig().Sources.ClaudeProjects))
	cfg.Sources.CopilotSessionState = ExpandPath(firstNonEmpty(cfg.Sources.CopilotSessionState, DefaultConfig().Sources.CopilotSessionState))
	cfg.Sources.HermesDatabase = ExpandPath(firstNonEmpty(cfg.Sources.HermesDatabase, DefaultConfig().Sources.HermesDatabase))
	cfg.Sources.OpenCodeDatabase = ExpandPath(firstNonEmpty(cfg.Sources.OpenCodeDatabase, DefaultConfig().Sources.OpenCodeDatabase))
	if cfg.Live.DefaultBackend == "" {
		cfg.Live.DefaultBackend = "herdr"
	}
	return cfg, nil
}

func EnsureDirs(cfg Config) error {
	return os.MkdirAll(filepath.Dir(cfg.Database), 0755)
}

func ExpandPath(path string) string {
	if path == "" {
		return ""
	}
	if path == "~" {
		home, _ := os.UserHomeDir()
		return home
	}
	if strings.HasPrefix(path, "~/") {
		home, _ := os.UserHomeDir()
		return filepath.Join(home, path[2:])
	}
	return os.ExpandEnv(path)
}

func firstNonEmpty(values ...string) string {
	for _, v := range values {
		if v != "" {
			return v
		}
	}
	return ""
}

func defaultHermesDatabase(home string) string {
	hermesHome := strings.TrimSpace(os.Getenv("HERMES_HOME"))
	var base string
	if hermesHome != "" {
		base = ExpandPath(hermesHome)
		if filepath.Base(filepath.Dir(base)) == "profiles" {
			return filepath.Join(base, "state.db")
		}
	} else {
		base = hermesBaseDir(home, runtime.GOOS, os.Getenv("LOCALAPPDATA"))
	}
	if os.Getenv("HERMES_S6_SUPERVISED_CHILD") == "" {
		profile, err := os.ReadFile(filepath.Join(base, "active_profile"))
		if err == nil {
			name := strings.TrimSpace(string(profile))
			if name != "" && name != "default" && filepath.Base(name) == name {
				return filepath.Join(base, "profiles", name, "state.db")
			}
		}
	}
	return filepath.Join(base, "state.db")
}

func defaultOpenCodeDatabase(home string) string {
	dataDir := openCodeDataDir(home)
	if override := os.Getenv("OPENCODE_DB"); override != "" {
		if override == ":memory:" || filepath.IsAbs(override) {
			return override
		}
		return filepath.Join(dataDir, "opencode", override)
	}
	return filepath.Join(dataDir, "opencode", "opencode.db")
}

func openCodeDataDir(home string) string {
	if dataDir := os.Getenv("XDG_DATA_HOME"); dataDir != "" {
		return ExpandPath(dataDir)
	}
	return filepath.Join(home, ".local", "share")
}

func hermesBaseDir(home, goos, localAppData string) string {
	if goos == "windows" {
		if localAppData == "" {
			localAppData = filepath.Join(home, "AppData", "Local")
		}
		return filepath.Join(localAppData, "hermes")
	}
	return filepath.Join(home, ".hermes")
}

package config

import (
	"os"
	"path/filepath"
	"testing"
)

func TestDefaultHermesDatabaseHonorsHomeAndActiveProfile(t *testing.T) {
	home := t.TempDir()
	customRoot := filepath.Join(home, "custom")
	if err := os.MkdirAll(customRoot, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(customRoot, "active_profile"), []byte("coder\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	t.Setenv("HERMES_HOME", customRoot)
	if got, want := defaultHermesDatabase(home), filepath.Join(customRoot, "profiles", "coder", "state.db"); got != want {
		t.Fatalf("root HERMES_HOME path = %q, want %q", got, want)
	}

	directProfile := filepath.Join(customRoot, "profiles", "direct")
	t.Setenv("HERMES_HOME", directProfile)
	if got, want := defaultHermesDatabase(home), filepath.Join(directProfile, "state.db"); got != want {
		t.Fatalf("profile HERMES_HOME path = %q, want %q", got, want)
	}

	t.Setenv("HERMES_HOME", "")
	base := filepath.Join(home, ".hermes")
	if err := os.MkdirAll(base, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(base, "active_profile"), []byte("coder\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	want := filepath.Join(base, "profiles", "coder", "state.db")
	if got := defaultHermesDatabase(home); got != want {
		t.Fatalf("profile path = %q, want %q", got, want)
	}
}

func TestDefaultOpenCodeDatabaseHonorsOverrides(t *testing.T) {
	home := t.TempDir()
	xdg := filepath.Join(home, "data")
	t.Setenv("XDG_DATA_HOME", xdg)
	t.Setenv("OPENCODE_DB", "custom.db")
	want := filepath.Join(xdg, "opencode", "custom.db")
	if got := defaultOpenCodeDatabase(home); got != want {
		t.Fatalf("relative override = %q, want %q", got, want)
	}

	absolute := filepath.Join(home, "absolute.db")
	t.Setenv("OPENCODE_DB", absolute)
	if got := defaultOpenCodeDatabase(home); got != absolute {
		t.Fatalf("absolute override = %q", got)
	}
}

func TestOpenCodeDataDirDefaultsToXDGConvention(t *testing.T) {
	home := t.TempDir()
	t.Setenv("XDG_DATA_HOME", "")
	if got, want := openCodeDataDir(home), filepath.Join(home, ".local", "share"); got != want {
		t.Fatalf("data dir = %q, want %q", got, want)
	}
}

func TestHermesBaseDirUsesWindowsLocalAppData(t *testing.T) {
	home := `C:\Users\test`
	if got, want := hermesBaseDir(home, "windows", `D:\Local`), filepath.Join(`D:\Local`, "hermes"); got != want {
		t.Fatalf("Hermes Windows base = %q, want %q", got, want)
	}
}

package core

import (
	"crypto/sha1"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

const (
	StatusNeedsAttention = "needs_attention"
	StatusWorking        = "working"
	StatusIdle           = "idle"
	StatusDone           = "done"
	StatusStale          = "stale"
	StatusUnknown        = "unknown"
)

type Session struct {
	ID             string
	Source         string
	NativeID       string
	ProjectPath    string
	Agent          string
	Title          string
	TitleSource    string
	GoalSummary    string
	Status         string
	Pinned         bool
	Tags           string
	LastActivityAt time.Time
	CreatedAt      time.Time
	UpdatedAt      time.Time
	ResumeCommand  string
	AttachCommand  string
	RawPath        string
}

type RuntimeInstance struct {
	ID            string
	SessionID     string
	Backend       string
	NativeID      string
	Surface       string
	ProjectPath   string
	Command       string
	Status        string
	AttachCommand string
	UpdatedAt     time.Time
}

type ScanResult struct {
	Source                  string
	Sessions                []Session
	Runtimes                []RuntimeInstance
	Skipped                 bool
	SessionSnapshotComplete bool
	SnapshotComplete        bool
	Message                 string
	Err                     error
}

func CanonicalID(source, nativeID string) string {
	sum := sha1.Sum([]byte(source + "\x00" + nativeID))
	return source + "-" + hex.EncodeToString(sum[:])[:12]
}

func RuntimeID(backend, nativeID string) string {
	sum := sha1.Sum([]byte(backend + "\x00" + nativeID))
	return backend + "-" + hex.EncodeToString(sum[:])[:12]
}

func ProjectID(path string) string {
	if path == "" {
		return ""
	}
	abs, err := filepath.Abs(path)
	if err != nil {
		abs = path
	}
	sum := sha1.Sum([]byte(abs))
	return "project-" + hex.EncodeToString(sum[:])[:12]
}

func ProjectName(path string) string {
	if path == "" {
		return "unknown project"
	}
	clean := filepath.Clean(path)
	base := filepath.Base(clean)
	if base == "." || base == string(filepath.Separator) || base == "" {
		return clean
	}
	return base
}

func DecodeClaudeProjectDir(name string) string {
	if strings.HasPrefix(name, "-") {
		decoded := strings.ReplaceAll(name, "-", string(filepath.Separator))
		if decoded != "" {
			return decoded
		}
	}
	return name
}

func ShellQuote(s string) string {
	if s == "" {
		return "''"
	}
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

func SanitizeName(s string) string {
	s = strings.TrimSpace(strings.ToLower(s))
	re := regexp.MustCompile(`[^a-z0-9_.-]+`)
	s = re.ReplaceAllString(s, "-")
	s = strings.Trim(s, "-")
	if s == "" {
		return "session"
	}
	if len(s) > 48 {
		return strings.Trim(s[:48], "-")
	}
	return s
}

func Truncate(s string, max int) string {
	s = strings.TrimSpace(strings.Join(strings.Fields(s), " "))
	if max <= 0 || len(s) <= max {
		return s
	}
	if max <= 3 {
		return s[:max]
	}
	return strings.TrimSpace(s[:max-3]) + "..."
}

func ExistingDir(path string) bool {
	info, err := os.Stat(path)
	return err == nil && info.IsDir()
}

func ExistingFile(path string) bool {
	info, err := os.Stat(path)
	return err == nil && !info.IsDir()
}

func NonZeroTime(t time.Time, fallback time.Time) time.Time {
	if t.IsZero() {
		return fallback
	}
	return t
}

func FormatTime(t time.Time) string {
	if t.IsZero() {
		return "-"
	}
	return t.Local().Format("2006-01-02 15:04")
}

func NewSession(source, nativeID string) Session {
	now := time.Now().UTC()
	return Session{
		ID:        CanonicalID(source, nativeID),
		Source:    source,
		NativeID:  nativeID,
		Status:    StatusUnknown,
		CreatedAt: now,
		UpdatedAt: now,
	}
}

func TmuxAttachCommand(session string) string {
	return fmt.Sprintf("tmux attach -t %s", ShellQuote(session))
}

package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/core"
	_ "modernc.org/sqlite"
)

type Store struct {
	db *sql.DB
}

type Filter struct {
	Source     string
	Status     string
	Query      string
	Tag        string
	Sort       string
	Limit      int
	PinnedOnly bool
}

func Open(path string) (*Store, error) {
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return nil, err
	}
	db.SetMaxOpenConns(1)
	s := &Store{db: db}
	if err := s.Migrate(context.Background()); err != nil {
		_ = db.Close()
		return nil, err
	}
	return s, nil
}

func (s *Store) Close() error {
	return s.db.Close()
}

func (s *Store) Migrate(ctx context.Context) error {
	stmts := []string{
		`PRAGMA foreign_keys = ON`,
		`CREATE TABLE IF NOT EXISTS sources (
			id TEXT PRIMARY KEY,
			kind TEXT NOT NULL,
			path TEXT,
			enabled INTEGER NOT NULL DEFAULT 1,
			last_scan_at TEXT,
			last_error TEXT
		)`,
		`CREATE TABLE IF NOT EXISTS projects (
			id TEXT PRIMARY KEY,
			path TEXT NOT NULL UNIQUE,
			name TEXT NOT NULL,
			updated_at TEXT NOT NULL
		)`,
		`CREATE TABLE IF NOT EXISTS sessions (
			id TEXT PRIMARY KEY,
			source TEXT NOT NULL,
			native_id TEXT NOT NULL,
			project_id TEXT,
			project_path TEXT,
			agent TEXT,
			title TEXT,
			goal_summary TEXT,
			status TEXT NOT NULL,
			last_activity_at TEXT,
			created_at TEXT NOT NULL,
			updated_at TEXT NOT NULL,
			resume_command TEXT,
			attach_command TEXT,
			raw_path TEXT,
			UNIQUE(source, native_id)
		)`,
		`CREATE TABLE IF NOT EXISTS runtime_instances (
			id TEXT PRIMARY KEY,
			session_id TEXT,
			backend TEXT NOT NULL,
			native_id TEXT NOT NULL,
			surface TEXT,
			project_path TEXT,
			command TEXT,
			status TEXT NOT NULL,
			attach_command TEXT,
			updated_at TEXT NOT NULL,
			UNIQUE(backend, native_id)
		)`,
		`CREATE TABLE IF NOT EXISTS summaries (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			session_id TEXT NOT NULL,
			provider TEXT NOT NULL,
			title TEXT,
			goal_summary TEXT,
			confidence REAL NOT NULL DEFAULT 0,
			created_at TEXT NOT NULL
		)`,
		`CREATE INDEX IF NOT EXISTS idx_sessions_source ON sessions(source)`,
		`CREATE INDEX IF NOT EXISTS idx_sessions_status ON sessions(status)`,
		`CREATE INDEX IF NOT EXISTS idx_sessions_last_activity ON sessions(last_activity_at DESC)`,
	}
	for _, stmt := range stmts {
		if _, err := s.db.ExecContext(ctx, stmt); err != nil {
			return err
		}
	}
	for _, col := range []struct {
		name string
		typ  string
	}{
		{"title_source", "TEXT NOT NULL DEFAULT 'scanner'"},
		{"pinned", "INTEGER NOT NULL DEFAULT 0"},
		{"tags", "TEXT NOT NULL DEFAULT ''"},
	} {
		ok, err := s.columnExists(ctx, "sessions", col.name)
		if err != nil {
			return err
		}
		if !ok {
			if _, err := s.db.ExecContext(ctx, `ALTER TABLE sessions ADD COLUMN `+col.name+` `+col.typ); err != nil {
				return err
			}
		}
	}
	return nil
}

func (s *Store) UpsertSource(ctx context.Context, id, kind, path, lastError string) error {
	now := time.Now().UTC().Format(time.RFC3339Nano)
	_, err := s.db.ExecContext(ctx, `INSERT INTO sources (id, kind, path, enabled, last_scan_at, last_error)
		VALUES (?, ?, ?, 1, ?, ?)
		ON CONFLICT(id) DO UPDATE SET kind = excluded.kind, path = excluded.path,
			last_scan_at = excluded.last_scan_at, last_error = excluded.last_error`,
		id, kind, path, now, lastError)
	return err
}

func (s *Store) UpsertSession(ctx context.Context, sess core.Session) error {
	if strings.TrimSpace(sess.Source) == "" || strings.TrimSpace(sess.NativeID) == "" {
		return fmt.Errorf("session source and native id are required")
	}
	return upsertSession(ctx, s.db, sess, false)
}

// ReplaceSessions atomically replaces one source's authoritative historical
// snapshot. Existing manual titles, pins, and tags survive rows that remain.
func (s *Store) ReplaceSessions(ctx context.Context, source string, sessions []core.Session) error {
	source = strings.TrimSpace(source)
	if source == "" {
		return fmt.Errorf("session source is required")
	}
	normalized := make([]core.Session, len(sessions))
	seen := make(map[string]struct{}, len(sessions))
	for index, session := range sessions {
		if session.Source == "" {
			session.Source = source
		}
		if session.Source != source {
			return fmt.Errorf("session source %q does not match snapshot source %q", session.Source, source)
		}
		session.NativeID = strings.TrimSpace(session.NativeID)
		if session.NativeID == "" {
			return fmt.Errorf("session native id is required")
		}
		if _, exists := seen[session.NativeID]; exists {
			return fmt.Errorf("duplicate native session id %q for source %q", session.NativeID, source)
		}
		seen[session.NativeID] = struct{}{}
		normalized[index] = session
	}

	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback() //nolint:errcheck

	for _, session := range normalized {
		if err := upsertSession(ctx, tx, session, true); err != nil {
			return err
		}
	}

	args := []any{source}
	query := `DELETE FROM sessions WHERE source = ?`
	if len(normalized) > 0 {
		placeholders := make([]string, 0, len(normalized))
		for _, session := range normalized {
			placeholders = append(placeholders, "?")
			args = append(args, session.NativeID)
		}
		query += ` AND native_id NOT IN (` + strings.Join(placeholders, ",") + `)`
	}
	if _, err := tx.ExecContext(ctx, query, args...); err != nil {
		return err
	}
	return tx.Commit()
}

func upsertSession(ctx context.Context, executor dbExecer, sess core.Session, replaceCreatedAt bool) error {
	now := time.Now().UTC()
	sess.UpdatedAt = now
	if sess.CreatedAt.IsZero() {
		sess.CreatedAt = now
	}
	if sess.Status == "" {
		sess.Status = core.StatusUnknown
	}
	projectID := ""
	if sess.ProjectPath != "" {
		projectID = core.ProjectID(sess.ProjectPath)
		if err := upsertProject(ctx, executor, projectID, sess.ProjectPath); err != nil {
			return err
		}
	}
	titleSource := sess.TitleSource
	if titleSource == "" {
		titleSource = "scanner"
	}
	_, err := executor.ExecContext(ctx, `INSERT INTO sessions
		(id, source, native_id, project_id, project_path, agent, title, title_source, goal_summary, status,
		 pinned, tags, last_activity_at, created_at, updated_at, resume_command, attach_command, raw_path)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
		ON CONFLICT(source, native_id) DO UPDATE SET
			project_id = excluded.project_id,
			project_path = excluded.project_path,
			agent = excluded.agent,
			title = CASE WHEN sessions.title_source = 'manual' THEN sessions.title WHEN excluded.title != '' THEN excluded.title ELSE sessions.title END,
			title_source = CASE WHEN sessions.title_source = 'manual' THEN sessions.title_source ELSE excluded.title_source END,
			goal_summary = CASE WHEN excluded.goal_summary != '' THEN excluded.goal_summary ELSE sessions.goal_summary END,
			status = excluded.status,
			last_activity_at = excluded.last_activity_at,
			created_at = CASE WHEN ? = 1 AND excluded.created_at != '' THEN excluded.created_at ELSE sessions.created_at END,
			updated_at = excluded.updated_at,
			resume_command = excluded.resume_command,
			attach_command = excluded.attach_command,
			raw_path = excluded.raw_path`,
		sess.ID, sess.Source, sess.NativeID, projectID, sess.ProjectPath, sess.Agent, sess.Title, titleSource,
		sess.GoalSummary, sess.Status, boolToInt(sess.Pinned), sess.Tags, encodeTime(sess.LastActivityAt), encodeTime(sess.CreatedAt),
		encodeTime(sess.UpdatedAt), sess.ResumeCommand, sess.AttachCommand, sess.RawPath, boolToInt(replaceCreatedAt))
	return err
}

func (s *Store) UpsertRuntime(ctx context.Context, rt core.RuntimeInstance) error {
	rt = normalizeRuntime(rt)
	if strings.TrimSpace(rt.Backend) == "" {
		return fmt.Errorf("runtime backend is required")
	}
	return upsertRuntime(ctx, s.db, rt)
}

// ReplaceRuntimes atomically replaces one backend's complete live snapshot.
// Callers must only use it after an authoritative provider scan succeeds.
func (s *Store) ReplaceRuntimes(ctx context.Context, backend string, runtimes []core.RuntimeInstance) error {
	backend = strings.TrimSpace(backend)
	if backend == "" {
		return fmt.Errorf("runtime backend is required")
	}
	normalized := make([]core.RuntimeInstance, len(runtimes))
	for index, runtime := range runtimes {
		if runtime.Backend == "" {
			runtime.Backend = backend
		}
		if runtime.Backend != backend {
			return fmt.Errorf("runtime backend %q does not match snapshot backend %q", runtime.Backend, backend)
		}
		normalized[index] = normalizeRuntime(runtime)
	}

	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback() //nolint:errcheck

	if _, err := tx.ExecContext(ctx, `DELETE FROM runtime_instances WHERE backend = ?`, backend); err != nil {
		return err
	}
	for _, runtime := range normalized {
		if err := upsertRuntime(ctx, tx, runtime); err != nil {
			return err
		}
	}
	return tx.Commit()
}

type dbExecer interface {
	ExecContext(context.Context, string, ...any) (sql.Result, error)
}

func upsertRuntime(ctx context.Context, executor dbExecer, rt core.RuntimeInstance) error {
	_, err := executor.ExecContext(ctx, `INSERT INTO runtime_instances
		(id, session_id, backend, native_id, surface, project_path, command, status, attach_command, updated_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
		ON CONFLICT(backend, native_id) DO UPDATE SET
			session_id = excluded.session_id,
			surface = excluded.surface,
			project_path = excluded.project_path,
			command = excluded.command,
			status = excluded.status,
			attach_command = excluded.attach_command,
			updated_at = excluded.updated_at`,
		rt.ID, rt.SessionID, rt.Backend, rt.NativeID, rt.Surface, rt.ProjectPath, rt.Command,
		rt.Status, rt.AttachCommand, encodeTime(rt.UpdatedAt))
	return err
}

func normalizeRuntime(rt core.RuntimeInstance) core.RuntimeInstance {
	if rt.UpdatedAt.IsZero() {
		rt.UpdatedAt = time.Now().UTC()
	}
	if rt.Status == "" {
		rt.Status = core.StatusUnknown
	}
	return rt
}

func (s *Store) ListSessions(ctx context.Context, filter Filter) ([]core.Session, error) {
	var where []string
	var args []any
	if filter.Source != "" {
		where = append(where, "source = ?")
		args = append(args, filter.Source)
	}
	if filter.Status != "" {
		where = append(where, "status = ?")
		args = append(args, filter.Status)
	}
	if filter.PinnedOnly {
		where = append(where, "pinned = 1")
	}
	if filter.Tag != "" {
		where = append(where, "(',' || tags || ',') LIKE ?")
		args = append(args, "%,"+filter.Tag+",%")
	}
	if filter.Query != "" {
		q := "%" + filter.Query + "%"
		where = append(where, "(title LIKE ? OR goal_summary LIKE ? OR project_path LIKE ? OR native_id LIKE ? OR agent LIKE ? OR tags LIKE ?)")
		args = append(args, q, q, q, q, q, q)
	}
	query := `SELECT id, source, native_id, project_path, agent, title, title_source, goal_summary, status,
		pinned, tags,
		last_activity_at, created_at, updated_at, resume_command, attach_command, raw_path FROM sessions`
	if len(where) > 0 {
		query += " WHERE " + strings.Join(where, " AND ")
	}
	query += orderBy(filter.Sort)
	if filter.Limit > 0 {
		query += " LIMIT ?"
		args = append(args, filter.Limit)
	}
	rows, err := s.db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var sessions []core.Session
	for rows.Next() {
		sess, err := scanSession(rows)
		if err != nil {
			return nil, err
		}
		sessions = append(sessions, sess)
	}
	return sessions, rows.Err()
}

func (s *Store) GetSession(ctx context.Context, ref string) (core.Session, error) {
	rows, err := s.db.QueryContext(ctx, `SELECT id, source, native_id, project_path, agent, title, title_source, goal_summary, status,
		pinned, tags, last_activity_at, created_at, updated_at, resume_command, attach_command, raw_path
		FROM sessions
		WHERE id = ? OR id LIKE ? OR native_id = ? OR native_id LIKE ?
		ORDER BY CASE WHEN id = ? THEN 0 ELSE 1 END, length(id)
		LIMIT 2`,
		ref, ref+"%", ref, ref+"%", ref)
	if err != nil {
		return core.Session{}, err
	}
	defer rows.Close()
	var found []core.Session
	for rows.Next() {
		sess, err := scanSession(rows)
		if err != nil {
			return core.Session{}, err
		}
		found = append(found, sess)
	}
	if err := rows.Err(); err != nil {
		return core.Session{}, err
	}
	if len(found) == 0 {
		return core.Session{}, sql.ErrNoRows
	}
	if len(found) > 1 && found[0].ID != ref {
		return core.Session{}, fmt.Errorf("ambiguous session reference %q", ref)
	}
	return found[0], nil
}

func (s *Store) RuntimeForSession(ctx context.Context, sessionID, preferredBackend string) (core.RuntimeInstance, error) {
	query := `SELECT id, session_id, backend, native_id, surface, project_path, command, status, attach_command, updated_at
		FROM runtime_instances WHERE session_id = ?`
	var args []any
	args = append(args, sessionID)
	if preferredBackend != "" {
		query += ` ORDER BY CASE WHEN backend = ? THEN 0 ELSE 1 END, updated_at DESC`
		args = append(args, preferredBackend)
	} else {
		query += ` ORDER BY updated_at DESC`
	}
	query += ` LIMIT 1`
	row := s.db.QueryRowContext(ctx, query, args...)
	return scanRuntime(row)
}

func (s *Store) UpdateSummary(ctx context.Context, sessionID, provider, title, summary, status string, confidence float64) error {
	now := time.Now().UTC()
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback() //nolint:errcheck
	_, err = tx.ExecContext(ctx, `INSERT INTO summaries
		(session_id, provider, title, goal_summary, confidence, created_at)
		VALUES (?, ?, ?, ?, ?, ?)`,
		sessionID, provider, title, summary, confidence, encodeTime(now))
	if err != nil {
		return err
	}
	parts := []string{"title = CASE WHEN title_source = 'manual' THEN title ELSE ? END", "title_source = CASE WHEN title_source = 'manual' THEN title_source ELSE ? END", "goal_summary = ?", "updated_at = ?"}
	args := []any{title, provider, summary, encodeTime(now)}
	if status != "" {
		parts = append(parts, "status = ?")
		args = append(args, status)
	}
	args = append(args, sessionID)
	_, err = tx.ExecContext(ctx, `UPDATE sessions SET `+strings.Join(parts, ", ")+` WHERE id = ?`, args...)
	if err != nil {
		return err
	}
	return tx.Commit()
}

func (s *Store) UpdateTitle(ctx context.Context, sessionID, title string) error {
	_, err := s.db.ExecContext(ctx, `UPDATE sessions SET title = ?, title_source = 'manual', updated_at = ? WHERE id = ?`,
		title, encodeTime(time.Now().UTC()), sessionID)
	return err
}

func (s *Store) UpdateStatus(ctx context.Context, sessionID, status string) error {
	_, err := s.db.ExecContext(ctx, `UPDATE sessions SET status = ?, updated_at = ? WHERE id = ?`,
		status, encodeTime(time.Now().UTC()), sessionID)
	return err
}

func (s *Store) UpdatePinned(ctx context.Context, sessionID string, pinned bool) error {
	_, err := s.db.ExecContext(ctx, `UPDATE sessions SET pinned = ?, updated_at = ? WHERE id = ?`,
		boolToInt(pinned), encodeTime(time.Now().UTC()), sessionID)
	return err
}

func (s *Store) UpdateTags(ctx context.Context, sessionID, tags string) error {
	_, err := s.db.ExecContext(ctx, `UPDATE sessions SET tags = ?, updated_at = ? WHERE id = ?`,
		normalizeTags(tags), encodeTime(time.Now().UTC()), sessionID)
	return err
}

func (s *Store) CountSessions(ctx context.Context) (int, error) {
	var count int
	err := s.db.QueryRowContext(ctx, `SELECT count(*) FROM sessions`).Scan(&count)
	return count, err
}

func (s *Store) upsertProject(ctx context.Context, id, path string) error {
	return upsertProject(ctx, s.db, id, path)
}

func upsertProject(ctx context.Context, executor dbExecer, id, path string) error {
	now := time.Now().UTC().Format(time.RFC3339Nano)
	_, err := executor.ExecContext(ctx, `INSERT INTO projects (id, path, name, updated_at)
		VALUES (?, ?, ?, ?)
		ON CONFLICT(path) DO UPDATE SET name = excluded.name, updated_at = excluded.updated_at`,
		id, path, core.ProjectName(path), now)
	return err
}

func (s *Store) columnExists(ctx context.Context, table, column string) (bool, error) {
	rows, err := s.db.QueryContext(ctx, `PRAGMA table_info(`+table+`)`)
	if err != nil {
		return false, err
	}
	defer rows.Close()
	for rows.Next() {
		var cid int
		var name, typ string
		var notNull int
		var defaultValue any
		var pk int
		if err := rows.Scan(&cid, &name, &typ, &notNull, &defaultValue, &pk); err != nil {
			return false, err
		}
		if name == column {
			return true, nil
		}
	}
	return false, rows.Err()
}

type scanner interface {
	Scan(dest ...any) error
}

func scanSession(row scanner) (core.Session, error) {
	var sess core.Session
	var last, created, updated sql.NullString
	var pinned int
	err := row.Scan(&sess.ID, &sess.Source, &sess.NativeID, &sess.ProjectPath, &sess.Agent,
		&sess.Title, &sess.TitleSource, &sess.GoalSummary, &sess.Status, &pinned, &sess.Tags, &last, &created, &updated,
		&sess.ResumeCommand, &sess.AttachCommand, &sess.RawPath)
	if err != nil {
		return core.Session{}, err
	}
	sess.Pinned = pinned == 1
	sess.LastActivityAt = decodeTime(last.String)
	sess.CreatedAt = decodeTime(created.String)
	sess.UpdatedAt = decodeTime(updated.String)
	return sess, nil
}

func orderBy(sort string) string {
	switch sort {
	case "title":
		return " ORDER BY title COLLATE NOCASE ASC"
	case "project":
		return " ORDER BY project_path COLLATE NOCASE ASC, COALESCE(last_activity_at, updated_at) DESC"
	case "source":
		return " ORDER BY source ASC, COALESCE(last_activity_at, updated_at) DESC"
	case "status":
		return " ORDER BY status ASC, COALESCE(last_activity_at, updated_at) DESC"
	default:
		return " ORDER BY pinned DESC, COALESCE(last_activity_at, updated_at) DESC, updated_at DESC"
	}
}

func boolToInt(v bool) int {
	if v {
		return 1
	}
	return 0
}

func normalizeTags(tags string) string {
	var out []string
	seen := make(map[string]bool)
	for _, tag := range strings.Split(tags, ",") {
		tag = strings.TrimSpace(strings.ToLower(tag))
		if tag == "" || seen[tag] {
			continue
		}
		seen[tag] = true
		out = append(out, tag)
	}
	return strings.Join(out, ",")
}

func scanRuntime(row scanner) (core.RuntimeInstance, error) {
	var rt core.RuntimeInstance
	var updated sql.NullString
	err := row.Scan(&rt.ID, &rt.SessionID, &rt.Backend, &rt.NativeID, &rt.Surface,
		&rt.ProjectPath, &rt.Command, &rt.Status, &rt.AttachCommand, &updated)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return core.RuntimeInstance{}, err
		}
		return core.RuntimeInstance{}, err
	}
	rt.UpdatedAt = decodeTime(updated.String)
	return rt, nil
}

func encodeTime(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	return t.UTC().Format(time.RFC3339Nano)
}

func decodeTime(s string) time.Time {
	if s == "" {
		return time.Time{}
	}
	t, _ := time.Parse(time.RFC3339Nano, s)
	return t
}

package store

import (
	"context"
	"database/sql"
	"errors"
	"path/filepath"
	"testing"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/core"
)

func TestUpsertAndGetSession(t *testing.T) {
	db, err := Open(filepath.Join(t.TempDir(), "sessions.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close() //nolint:errcheck
	session := core.NewSession("test", "native")
	session.ProjectPath = t.TempDir()
	session.Agent = "agent"
	session.Title = "Test session"
	session.LastActivityAt = time.Now().UTC()
	if err := db.UpsertSession(context.Background(), session); err != nil {
		t.Fatal(err)
	}
	got, err := db.GetSession(context.Background(), session.ID[:8])
	if err != nil {
		t.Fatal(err)
	}
	if got.ID != session.ID || got.Title != session.Title {
		t.Fatalf("unexpected session: %#v", got)
	}
}

func TestReplaceRuntimesIsAtomicPerBackend(t *testing.T) {
	db, err := Open(filepath.Join(t.TempDir(), "sessions.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close() //nolint:errcheck
	ctx := context.Background()

	for _, runtime := range []core.RuntimeInstance{
		{ID: "tmux-1", SessionID: "session-1", Backend: "tmux", NativeID: "%1"},
		{ID: "tmux-2", SessionID: "session-2", Backend: "tmux", NativeID: "%2"},
		{ID: "herdr-1", SessionID: "session-3", Backend: "herdr", NativeID: "w1:p1"},
	} {
		if err := db.UpsertRuntime(ctx, runtime); err != nil {
			t.Fatal(err)
		}
	}

	if err := db.ReplaceRuntimes(ctx, "tmux", []core.RuntimeInstance{{
		ID:        "tmux-2",
		SessionID: "session-2",
		Backend:   "tmux",
		NativeID:  "%2",
		Status:    core.StatusWorking,
	}}); err != nil {
		t.Fatal(err)
	}
	if _, err := db.RuntimeForSession(ctx, "session-1", "tmux"); !errors.Is(err, sql.ErrNoRows) {
		t.Fatalf("removed tmux row still present: %v", err)
	}
	got, err := db.RuntimeForSession(ctx, "session-2", "tmux")
	if err != nil || got.Status != core.StatusWorking {
		t.Fatalf("replacement row missing: %+v, %v", got, err)
	}
	if _, err := db.RuntimeForSession(ctx, "session-3", "herdr"); err != nil {
		t.Fatalf("other backend was pruned: %v", err)
	}

	if err := db.ReplaceRuntimes(ctx, "tmux", nil); err != nil {
		t.Fatal(err)
	}
	if _, err := db.RuntimeForSession(ctx, "session-2", "tmux"); !errors.Is(err, sql.ErrNoRows) {
		t.Fatalf("empty complete snapshot did not clear backend: %v", err)
	}
}

func TestReplaceSessionsPreservesManualMetadataAndPrunes(t *testing.T) {
	db, err := Open(filepath.Join(t.TempDir(), "sessions.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close() //nolint:errcheck
	ctx := context.Background()

	keep := core.NewSession("hermes", "keep")
	keep.Title = "Scanner title"
	keep.ProjectPath = "/repo"
	keep.CreatedAt = time.Unix(100, 0).UTC()
	remove := core.NewSession("hermes", "remove")
	remove.Title = "Remove me"
	if err := db.ReplaceSessions(ctx, "hermes", []core.Session{keep, remove}); err != nil {
		t.Fatal(err)
	}
	if err := db.UpdateTitle(ctx, keep.ID, "Manual title"); err != nil {
		t.Fatal(err)
	}
	if err := db.UpdatePinned(ctx, keep.ID, true); err != nil {
		t.Fatal(err)
	}
	if err := db.UpdateTags(ctx, keep.ID, "review,mvp"); err != nil {
		t.Fatal(err)
	}

	keep.Title = "New scanner title"
	keep.ProjectPath = "/repo/new"
	keep.CreatedAt = time.Unix(200, 0).UTC()
	if err := db.ReplaceSessions(ctx, "hermes", []core.Session{keep}); err != nil {
		t.Fatal(err)
	}
	got, err := db.GetSession(ctx, keep.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.Title != "Manual title" ||
		!got.Pinned ||
		got.Tags != "review,mvp" ||
		got.ProjectPath != "/repo/new" ||
		got.CreatedAt.Unix() != 200 {
		t.Fatalf("manual metadata or scanner update lost: %+v", got)
	}
	if _, err := db.GetSession(ctx, remove.ID); !errors.Is(err, sql.ErrNoRows) {
		t.Fatalf("removed source session still present: %v", err)
	}
}

func TestUpsertSessionPreservesLiveCreationTime(t *testing.T) {
	db, err := Open(filepath.Join(t.TempDir(), "sessions.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close() //nolint:errcheck
	ctx := context.Background()

	session := core.NewSession("tmux", "pane")
	session.Title = "Live"
	session.CreatedAt = time.Unix(100, 0).UTC()
	if err := db.UpsertSession(ctx, session); err != nil {
		t.Fatal(err)
	}
	session.CreatedAt = time.Unix(200, 0).UTC()
	if err := db.UpsertSession(ctx, session); err != nil {
		t.Fatal(err)
	}
	got, err := db.GetSession(ctx, session.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.CreatedAt.Unix() != 100 {
		t.Fatalf("live upsert reset creation time: %s", got.CreatedAt)
	}
}
